def solve(grid):
    """Count islands of 1s in a 0/1 grid (4-directional connectivity).
    Iterative flood fill (no recursion, safe for huge grids); does not
    mutate the caller's grid."""
    if not grid:
        return 0
    g = [list(row) for row in grid]
    rows = len(g)
    count = 0
    for i in range(rows):
        row = g[i]
        for j in range(len(row)):
            if row[j] == 1:
                count += 1
                row[j] = 0
                stack = [(i, j)]
                while stack:
                    x, y = stack.pop()
                    if x > 0 and g[x - 1][y] == 1:
                        g[x - 1][y] = 0
                        stack.append((x - 1, y))
                    if x + 1 < rows and y < len(g[x + 1]) and g[x + 1][y] == 1:
                        g[x + 1][y] = 0
                        stack.append((x + 1, y))
                    if y > 0 and g[x][y - 1] == 1:
                        g[x][y - 1] = 0
                        stack.append((x, y - 1))
                    if y + 1 < len(g[x]) and g[x][y + 1] == 1:
                        g[x][y + 1] = 0
                        stack.append((x, y + 1))
    return count

