code:
def solve(coins, amount):
    """Fewest coins summing to amount with unlimited supply of each coin
    value (complete knapsack DP). Returns -1 if impossible."""
    if amount == 0:
        return 0
    INF = float('inf')
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

