def solve(path: str) -> str:
    """Simplify an absolute Unix file path.
    Resolve '.' (current directory) and '..' (parent directory), remove duplicate slashes,
    and ensure the result starts with a single '/' and has no trailing slash (except root).
    """
    parts = []
    for comp in path.split('/'):
        if comp == '' or comp == '.':
            # skip empty and current directory components
            continue
        if comp == '..':
            # go up one directory if possible
            if parts:
                parts.pop()
        else:
            parts.append(comp)
    simplified = '/' + '/'.join(parts)
    # Ensure root is just '/'
    return simplified if simplified != '' else '/'

