def solve(grid):
    """Count the number of islands (connected components of 1s) in a grid.
    An island is formed by horizontally or vertically adjacent 1s.
    """
    if not grid or not any(grid):
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    if cols == 0:
        return 0
    visited = [[False] * cols for _ in range(rows)]
    def bfs(sr, sc):
        stack = [(sr, sc)]
        while stack:
            r, c = stack.pop()
            if r < 0 or r >= rows or c < 0 or c >= cols:
                continue
            if visited[r][c] or grid[r][c] == 0:
                continue
            visited[r][c] = True
            stack.append((r - 1, c))
            stack.append((r + 1, c))
            stack.append((r, c - 1))
            stack.append((r, c + 1))
    islands = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                islands += 1
                bfs(i, j)
    return islands

