def solve(n, b):
    """Return n written in base b (2-36) using digits 0-9 then lowercase
    letters, with a leading '-' for negative n."""
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    neg = n < 0
    n = abs(n)
    out = []
    while n:
        n, r = divmod(n, b)
        out.append(digits[r])
    if neg:
        out.append('-')
    return ''.join(reversed(out))

